// One Telegram message per row from script_approvals_due(). System text is English; the script
// title and preview are quoted Vietnamese video content. Callback data stays under Telegram's
// 64-byte limit: a1:<A|G|R>:<32-hex token>.
const rows = $input.all().filter((item) => typeof item.json.token === 'string');
return rows.map(({ json: row }) => {
  const script = (typeof row.script === 'string' ? JSON.parse(row.script) : row.script) || {};
  const shortId = String(row.video_id).slice(0, 8);
  const header = row.kind === 'REMINDER'
    ? '[AI Video] Reminder: script approval pending (A1)'
    : '[AI Video] Script ready for approval (A1)';
  const text = [
    header,
    `Video ${shortId} v${row.version}`,
    `Title: ${script.title ?? '?'}`,
    `${script.total_seconds ?? '?'} s, ${script.scene_count ?? '?'} scenes, ${script.narration_chars ?? '?'} narration characters (TTS)`,
    '',
    String(script.preview ?? '').slice(0, 3000),
    '',
    `Expires: ${new Date(row.expires_at).toISOString().replace('T', ' ').slice(0, 16)} UTC`,
  ].join('\n');
  return { json: { text, approve: `a1:A:${row.token}`, regenerate: `a1:G:${row.token}`, reject: `a1:R:${row.token}` } };
});
